const listTasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const getTask = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

function sendJson(response, status, data) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(data));
}

async function handle(request, response) {
  const url = new URL(request.url, 'http://localhost');
  if (url.pathname === '/health' && request.method === 'GET') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && request.method === 'GET') {
    return sendJson(response, 200, listProjects.all());
  }
  if (url.pathname === '/api/projects' && request.method === 'POST') {
    let body;
    try {
      const chunks = [];
      for await (const chunk of request) chunks.push(chunk);
      body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request body' });
    }
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const result = createProject.run(name);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    if (!getProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, listTasks.all(projectId));
  }
  if (tasksMatch && request.method === 'POST') {
    let body;
    try {
      const chunks = [];
      for await (const chunk of request) chunks.push(chunk);
      body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch { return sendJson(response, 400, { error: 'Invalid request body' }); }
    const title = typeof body?.title === 'string' ? body.title.trim() : '';
    if (!title) return sendJson(response, 400, { error: 'Task title is required' });
    const projectId = Number(tasksMatch[1]);
    if (!getProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    const result = createTask.run(projectId, title);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), title, completed: 0 });
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    let body;
    try {
      const chunks = [];
      for await (const chunk of request) chunks.push(chunk);
      body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch { return sendJson(response, 400, { error: 'Invalid request body' }); }
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    if (typeof body?.completed !== 'boolean') return sendJson(response, 400, { error: 'Invalid completion state' });
    if (!getTask.get(taskId) || !updateTask.run(body.completed ? 1 : 0, taskId, projectId).changes) return sendJson(response, 404, { error: 'Task not found' });
    return sendJson(response, 200, { id: taskId, completed: body.completed });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && request.method === 'GET') {
    const project = getProject.get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, project) : sendJson(response, 404, { error: 'Project not found' });
  }
  if (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname)) {
    try {
      const html = await readFile(path.join(root, 'public', 'index.html'));
      response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return response.end(html);
    } catch {
      return sendJson(response, 500, { error: 'Application unavailable' });
    }
  }
  if (url.pathname === '/app.js' || url.pathname === '/styles.css') {
    try {
      const filename = url.pathname.slice(1);
      const content = await readFile(path.join(root, 'public', filename));
      response.writeHead(200, { 'Content-Type': filename.endsWith('.js') ? 'text/javascript; charset=utf-8' : 'text/css; charset=utf-8' });
      return response.end(content);
    } catch {
      return sendJson(response, 404, { error: 'Not found' });
    }
  }
  sendJson(response, 404, { error: 'Not found' });
}

const server = createServer((request, response) => {
  handle(request, response).catch(() => sendJson(response, 500, { error: 'Internal server error' }));
});
const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');

function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

const listView = document.querySelector('#projects-view');
const detailView = document.querySelector('#detail-view');
const list = document.querySelector('#project-list');
const form = document.querySelector('#project-form');
const nameInput = document.querySelector('#project-name');
const alert = document.querySelector('#alert');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const taskList = document.querySelector('#task-list');
const taskFilter = document.querySelector('#task-filter');
let currentProjectId = null;

async function request(url, options) {
  const response = await fetch(url, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}

async function renderList() {
  currentProjectId = null;
  listView.hidden = false;
  detailView.hidden = true;
  const projects = await request('/api/projects');
  list.replaceChildren();
  for (const project of projects) {
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
    row.append(name, open);
    list.append(row);
  }
}

async function renderTasks() {
  const tasks = await request(`/api/projects/${currentProjectId}/tasks`);
  taskList.replaceChildren();
  const filter = taskFilter.value;
  for (const task of tasks) {
    if (filter === 'Open' && task.completed || filter === 'Completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'project-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      try {
        await request(`/api/projects/${currentProjectId}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked })
        });
        await renderTasks();
      } catch (error) { taskAlert.textContent = error.message; taskAlert.hidden = false; }
    });
    row.append(title, checkbox);
    taskList.append(row);
  }
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (!match) return renderList();
  try {
    const project = await request(`/api/projects/${match[1]}`);
    currentProjectId = project.id;
    listView.hidden = true;
    detailView.hidden = false;
    document.querySelector('#project-title').textContent = project.name;
    await renderTasks();
  } catch {
    history.replaceState(null, '', '/');
    await renderList();
  }
}

form.addEventListener('submit', async event => {
  event.preventDefault();
  const name = nameInput.value.trim();
  if (!name) {
    alert.textContent = 'Project name is required';
    alert.hidden = false;
    return;
  }
  alert.textContent = '';
  alert.hidden = true;
  try {
    await request('/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name })
    });
    nameInput.value = '';
    await renderList();
  } catch (error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
});

taskForm.addEventListener('submit', async event => {
  event.preventDefault();
  const title = taskInput.value.trim();
  if (!title) {
    taskAlert.textContent = 'Task title is required';
    taskAlert.hidden = false;
    return;
  }
  try {
    await request(`/api/projects/${currentProjectId}/tasks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title })
    });
    taskInput.value = '';
    taskAlert.hidden = true;
    await renderTasks();
  } catch (error) { taskAlert.textContent = error.message; taskAlert.hidden = false; }
});
taskFilter.addEventListener('change', () => renderTasks().catch(error => {
  taskAlert.textContent = error.message;
  taskAlert.hidden = false;
}));
document.querySelector('#back-button').addEventListener('click', () => { location.href = '/'; });
window.addEventListener('popstate', renderRoute);
renderRoute().catch(() => {
  alert.textContent = 'Unable to load projects';
  alert.hidden = false;
});

* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #202938; font: 16px/1.5 system-ui, sans-serif; }
main { width: min(720px, calc(100% - 32px)); margin: 64px auto; }
section { padding: 32px; background: white; border: 1px solid #e1e6ee; border-radius: 12px; box-shadow: 0 8px 24px #26354a0a; }
h1 { margin: 0 0 24px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-row, .project-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
input { min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #aeb8c7; border-radius: 6px; font: inherit; }
input[type="checkbox"] { min-width: auto; flex: 0 0 auto; width: 20px; height: 20px; }
select { padding: 8px 12px; border: 1px solid #aeb8c7; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #315dcc; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #254ba9; }
.project-row { padding: 16px 0; border-bottom: 1px solid #e6eaf0; }
.project-row:first-child { margin-top: 20px; }
#alert { color: #b42318; margin-bottom: 0; }
[hidden] { display: none !important; }
@media (max-width: 480px) { main { margin: 24px auto; } section { padding: 22px; } .form-row { align-items: stretch; flex-direction: column; } }

